class Solution {
public:
    void heapifyUp(vector<int> &nums,int index){
        int parentIndex = (index - 1) / 2;
        if(nums[parentIndex] > nums[index]){
            swap(nums[parentIndex],nums[index]);
             heapifyUp(nums,parentIndex);
        }
        return;
    }
    void heapifyDown(vector<int>& nums,int index){
        int n = nums.size();
        int smallest = index;

        int lChild = 2 * index + 1;
        int rChild = 2 * index + 2;

        if(lChild < n && nums[lChild] < nums[smallest]){
            smallest = lChild;
        }
        if(rChild < n && nums[rChild] < nums[smallest]){
            smallest = rChild;
        }
        if(index != smallest){
            swap(nums[index],nums[smallest]);
            heapifyDown(nums,smallest);
        }
        return;
    }
    void heapify(vector<int> &nums, int ind, int val) {
      int n = nums.size();

      if(nums[ind] > val){
        nums[ind] = val;
        heapifyUp(nums,ind);
      } else {
        nums[ind] = val;
        heapifyDown(nums,ind);
      }
      return;
    }
};
